<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api';const plans=['trial','basic','pro','custom'],plan=ref('trial'),features=ref<any[]>([]),loading=ref(false),saving=ref(false),error=ref('');async function load(){loading.value=true;error.value='';try{const[definitions,assigned]=await Promise.all([api('/api/v2/platform/features'),api(`/api/v2/platform/plans/${plan.value}/features`)]);const map=new Map<string,any>(assigned.items.map((x:any)=>[x.feature_code,x]));features.value=definitions.items.map((x:any)=>({code:x.feature_code,name:x.feature_name,enabled:map.get(x.feature_code)?.enabled??x.default_enabled,limits:map.get(x.feature_code)?.limits||{}}))}catch(e:any){error.value=e.message}finally{loading.value=false}}async function save(){if(!window.confirm(`保存后，使用 ${plan.value} 套餐的企业会立即刷新功能配置。确认继续吗？`))return;saving.value=true;try{await api(`/api/v2/platform/plans/${plan.value}/features`,{method:'PUT',body:JSON.stringify({items:features.value.map(x=>({feature_code:x.code,enabled:x.enabled,limits:x.limits}))})});await load()}catch(e:any){error.value=e.message}finally{saving.value=false}}onMounted(load);</script>
<template><section class="panel"><header class="panel-head"><div><span class="eyebrow">PLAN ENTITLEMENTS</span><h2>订阅与套餐功能</h2><p>设置每个套餐默认包含的功能。企业覆盖和设备覆盖拥有更高优先级。</p></div><button class="primary" :disabled="saving" @click="save">{{saving?'正在保存…':'保存套餐配置'}}</button></header><div class="toolbar"><select v-model="plan" @change="load"><option v-for="x in plans" :value="x">{{x}}</option></select></div><div v-if="loading" class="state-inline">正在获取套餐功能……</div><div v-else-if="error" class="state-inline error"><b>暂时无法加载套餐</b><span>{{error}}</span><button @click="load">立即重试</button></div><div v-else class="entitlement-list"><label v-for="x in features" :key="x.code"><input v-model="x.enabled" type="checkbox"><span><b>{{x.name}}</b><small>{{x.code}}</small></span><em>{{x.enabled?'套餐包含':'不包含'}}</em></label></div></section></template>
